package dev.dydiscord;
import dev.dydiscord.config.*;
import dev.dydiscord.linking.*;
import dev.dydiscord.storage.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class LinkingTest {
    @TempDir Path folder;Store store;Linking linking;TestSupport.Time time;Settings settings;UUID uuid;
    static final String D1="123456789012345678",D2="223456789012345678";
    @BeforeEach void setup()throws Exception{store=new Store(folder.resolve("data.db"));time=new TestSupport.Time();settings=TestSupport.settings();linking=new Linking(store,time,new SecureRandom());uuid=UUID.randomUUID();}
    @AfterEach void close()throws Exception{store.close();}
    String issue(UUID id)throws Exception{return linking.issue(id,"Alice",1,settings,true).code();}
    Store.Link redeem(String code,String discord)throws Exception{return linking.redeem(code,discord,settings,true,c->true);}
    @Test void formatAndCooldown()throws Exception{String code=issue(uuid);assertEquals(settings.codeLength(),code.length());assertTrue(code.matches("[A-HJ-NP-Z2-9]{6,16}"));assertThrows(Linking.Rejected.class,()->issue(uuid));time.advance(30);String newer=issue(uuid);assertTrue(linking.inspect(code).isEmpty());assertTrue(linking.inspect(newer).isPresent());}
    @Test void exactExpiryBoundary()throws Exception{String code=issue(uuid);time.advance(299);assertTrue(linking.inspect(code).isPresent());time.advance(1);assertThrows(Linking.Rejected.class,()->redeem(code,D1));}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(ints={1,2})
    void codeExpiringDuringOwnerValidationCannotCommit(int expiresAtCheck)throws Exception{
        String code=issue(uuid);time.advance(299);var checks=new java.util.concurrent.atomic.AtomicInteger();
        assertEquals("invalid-code",assertThrows(Linking.Rejected.class,()->linking.redeem(code,D1,settings,true,c->{if(checks.incrementAndGet()==expiresAtCheck)time.advance(1);return true;})).key);
        assertTrue(store.byUuid(uuid).isEmpty());assertTrue(store.byDiscord(D1).isEmpty());assertTrue(store.writable());
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"permission","audit","final-permission"})
    void confirmationExpiringWhileValidationOrAuditWaitsCannotUnlink(String stage)throws Exception{
        Store.Link record=redeem(issue(uuid),D1);String token=linking.confirm("admin",record,"leaf","reason",30);time.advance(29);var checks=new java.util.concurrent.atomic.AtomicInteger();
        assertEquals("confirmation-invalid",assertThrows(Linking.Rejected.class,()->linking.remove(token,"admin",p->{int check=checks.incrementAndGet();if(stage.equals("permission")&&check==1||stage.equals("final-permission")&&check==2)time.advance(1);return true;},c->{if(stage.equals("audit"))time.advance(1);})).key);
        assertEquals(record,store.byUuid(uuid).orElseThrow());assertTrue(store.writable());assertTrue(linking.pending(token,"admin").isEmpty());
    }
    @Test void parallelSameCodeHasOneWinner()throws Exception{String code=issue(uuid);ExecutorService pool=Executors.newFixedThreadPool(2);try{CountDownLatch start=new CountDownLatch(1);List<Future<Boolean>> results=new ArrayList<>();for(String d:List.of(D1,D2))results.add(pool.submit(()->{start.await();try{redeem(code,d);return true;}catch(Exception e){return false;}}));start.countDown();int won=0;for(Future<Boolean> result:results)if(result.get(5,TimeUnit.SECONDS))won++;assertEquals(1,won);assertTrue(store.byUuid(uuid).isPresent());}finally{pool.shutdownNow();}}
    @Test void discordAndUuidCannotBeTransferred()throws Exception{String first=issue(uuid);redeem(first,D1);String second=issue(UUID.randomUUID());assertThrows(Linking.Rejected.class,()->redeem(second,D1));assertThrows(Linking.Rejected.class,()->issue(uuid));}
    @Test void invalidActorGuildAndPermissionDoNotConsumeCode()throws Exception{String code=issue(uuid);assertThrows(Linking.Rejected.class,()->linking.redeem(code,D1,settings,false,c->true));assertThrows(Linking.Rejected.class,()->linking.redeem(code,D1,settings,true,c->false));assertTrue(linking.inspect(code).isPresent());}
    @Test void revokedOwnerBeforeCommitRollsBackAndPreservesCode()throws Exception{String code=issue(uuid);java.util.concurrent.atomic.AtomicInteger checks=new java.util.concurrent.atomic.AtomicInteger();assertEquals("invalid-code",assertThrows(Linking.Rejected.class,()->linking.redeem(code,D1,settings,true,c->checks.incrementAndGet()==1)).key);assertTrue(store.byUuid(uuid).isEmpty());assertTrue(linking.inspect(code).isPresent());assertTrue(store.writable());redeem(code,D1);assertTrue(store.byUuid(uuid).isPresent());}
    @Test void ownerDisconnectAndRestartInvalidateCodes()throws Exception{String code=issue(uuid);linking.leave(uuid);assertThrows(Linking.Rejected.class,()->redeem(code,D1));time.advance(30);String second=issue(uuid);linking.invalidate();assertThrows(Linking.Rejected.class,()->redeem(second,D1));}
    @Test void disabledLinkingAndUnavailableBotRejectCodes()throws Exception{var config=TestSupport.config(folder.resolve("config"));config.change("config.yml","linking.enabled",false);assertEquals("linking-disabled",assertThrows(Linking.Rejected.class,()->linking.issue(uuid,"Alice",1,config.active().settings(),true)).key);assertEquals("bot-unavailable",assertThrows(Linking.Rejected.class,()->linking.issue(uuid,"Alice",1,settings,false)).key);}
    @Test void invalidAttemptsHaveUserAndGlobalLimits()throws Exception{for(int i=0;i<5;i++)assertEquals("invalid-code",assertThrows(Linking.Rejected.class,()->redeem("BAD",D1)).key);assertEquals("rate-limit",assertThrows(Linking.Rejected.class,()->redeem("BAD",D1)).key);assertEquals("invalid-code",assertThrows(Linking.Rejected.class,()->redeem("BAD",D2)).key);time.advance(300);assertEquals("invalid-code",assertThrows(Linking.Rejected.class,()->redeem("BAD",D1)).key);}
    @Test void hugeInputIsRejectedWithoutPersistence()throws Exception{assertThrows(Linking.Rejected.class,()->redeem("A".repeat(100000),D1));assertTrue(store.byDiscord(D1).isEmpty());}
    @Test void globalAttemptLimitAppliesAcrossAccounts()throws Exception{for(int i=0;i<1000;i++){String id=Long.toString(123456789012345678L+i);assertEquals("invalid-code",assertThrows(Linking.Rejected.class,()->redeem("BAD",id)).key);}assertEquals("rate-limit",assertThrows(Linking.Rejected.class,()->redeem("BAD",D2)).key);}
    @Test void restartInvalidatesConfirmationButPreservesAccount()throws Exception{Store.Link record=redeem(issue(uuid),D1);String token=linking.confirm("mc",record,"leaf","",30);linking.invalidate();assertThrows(Linking.Rejected.class,()->linking.remove(token,"mc",p->true,c->{}));assertTrue(store.byUuid(uuid).isPresent());}
    @Test void parallelUnlinkHasOneWinner()throws Exception{Store.Link record=redeem(issue(uuid),D1);String mc=linking.confirm("mc",record,"leaf","",30),dc=linking.confirm("dc",record,"owner","",30);ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<Boolean>> futures=List.of(pool.submit(()->{try{return linking.remove(mc,"mc",p->true,c->{});}catch(Linking.Rejected e){return false;}}),pool.submit(()->{try{return linking.remove(dc,"dc",p->true,c->{});}catch(Linking.Rejected e){return false;}}));int count=0;for(var future:futures)if(future.get())count++;assertEquals(1,count);assertTrue(store.byUuid(uuid).isEmpty());}finally{pool.shutdownNow();}}
    @Test void confirmationBoundToActorAndSingleUse()throws Exception{Store.Link record=redeem(issue(uuid),D1);String token=linking.confirm("dc:"+D1,record,"owner","",30);assertThrows(Linking.Rejected.class,()->linking.remove(token,"dc:"+D2,p->true,c->{}));assertTrue(linking.remove(token,"dc:"+D1,p->true,c->{}));assertThrows(Linking.Rejected.class,()->linking.remove(token,"dc:"+D1,p->true,c->{}));}
    @Test void deniedAndExpiredConfirmationsCannotMutate()throws Exception{Store.Link record=redeem(issue(uuid),D1);String token=linking.confirm("mc",record,"leaf","",30);assertThrows(Linking.Rejected.class,()->linking.remove(token,"mc",p->false,c->{}));assertTrue(store.byUuid(uuid).isPresent());String next=linking.confirm("mc",record,"leaf","",30);time.advance(30);assertThrows(Linking.Rejected.class,()->linking.remove(next,"mc",p->true,c->{}));}
    @Test void changedRecordVersionPreventsStaleConfirmation()throws Exception{Store.Link record=redeem(issue(uuid),D1);String token=linking.confirm("dc",record,"owner","",30);store.unlink(record);store.link(uuid,D2,"Alice",time.instant());assertThrows(Linking.Rejected.class,()->linking.remove(token,"dc",p->true,c->{}));assertEquals(D2,store.byUuid(uuid).orElseThrow().discord());}
    @Test void auditFailurePreventsAdminUnlink()throws Exception{Store.Link record=redeem(issue(uuid),D1);String token=linking.confirm("admin",record,"leaf","reason",30);assertThrows(IllegalStateException.class,()->linking.remove(token,"admin",p->true,c->{throw new IllegalStateException();}));assertTrue(store.byUuid(uuid).isPresent());}
    @Test void permissionLossWhileAuditingPreventsUnlink()throws Exception{Store.Link record=redeem(issue(uuid),D1);String token=linking.confirm("admin",record,"leaf","reason",30);java.util.concurrent.atomic.AtomicBoolean allowed=new java.util.concurrent.atomic.AtomicBoolean(true);assertThrows(Linking.Rejected.class,()->linking.remove(token,"admin",p->allowed.get(),c->allowed.set(false)));assertTrue(store.byUuid(uuid).isPresent());}
    @Test void preferenceNameAndUtcSurviveReopen()throws Exception{Store.Link record=redeem(issue(uuid),D1);store.preference(uuid,"auto");store.updateName(uuid,"NewName");store.close();store=new Store(folder.resolve("data.db"));assertEquals("NewName",store.byUuid(uuid).orElseThrow().name());assertEquals(record.linkedAt(),store.byUuid(uuid).orElseThrow().linkedAt());assertEquals("auto",store.preferences().get(uuid));}
    @Test void receiptsDeduplicateAndAmbiguousCommandsNeverReplay()throws Exception{assertTrue(store.accept("m1",time.instant()));assertFalse(store.accept("m1",time.instant()));store.close();store=new Store(folder.resolve("data.db"));assertFalse(store.accept("m1",time.instant()));}
    @Test void corruptDatabaseIsPreserved()throws Exception{Path bad=folder.resolve("bad.db");byte[] content="not a sqlite database".getBytes();Files.write(bad,content);assertThrows(Exception.class,()->new Store(bad));assertArrayEquals(content,Files.readAllBytes(bad));}
    @Test void usernameIsSavedInSameCommitAsCodeRedemption()throws Exception{String code=issue(uuid);Store.Link saved=linking.redeem(code,D1,"the_claww",settings,true,c->true);assertEquals("the_claww",saved.discordName());assertEquals(saved,store.byUuid(uuid).orElseThrow());assertTrue(linking.inspect(code).isEmpty());store.close();store=new Store(folder.resolve("data.db"));assertEquals(saved,store.byDiscord(D1).orElseThrow());}
    @Test void revokedUsernameAwareRedemptionRollsBackAndLeavesCodeActive()throws Exception{String code=issue(uuid);java.util.concurrent.atomic.AtomicInteger checks=new java.util.concurrent.atomic.AtomicInteger();assertEquals("invalid-code",assertThrows(Linking.Rejected.class,()->linking.redeem(code,D1,"the_claww",settings,true,c->checks.incrementAndGet()==1)).key);assertTrue(store.byUuid(uuid).isEmpty());assertTrue(linking.inspect(code).isPresent());assertTrue(store.writable());}
    @Test void futureDatabaseSchemaIsRejectedWithoutDestroyingExistingLinks()throws Exception{Store.Link existing=redeem(issue(uuid),D1);store.close();try(var c=java.sql.DriverManager.getConnection("jdbc:sqlite:"+folder.resolve("data.db"));var s=c.createStatement()){s.execute("UPDATE schema_version SET version=4");}assertThrows(java.sql.SQLException.class,()->new Store(folder.resolve("data.db")));try(var c=java.sql.DriverManager.getConnection("jdbc:sqlite:"+folder.resolve("data.db"));var s=c.createStatement();var r=s.executeQuery("SELECT uuid,discord FROM links")){assertTrue(r.next());assertEquals(existing.uuid().toString(),r.getString(1));assertEquals(D1,r.getString(2));}}
}
